const D = { scale: 1, energy: .6, density: .5, speed: 1, drive: .35, hue: 200, x: .5, y: .5, style: 'water', seed: 0, alpha: 100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

// ---- coarse buffer ----
const BW = Math.max(360, Math.min(720, Math.round(width / 2.4))), BH = Math.max(48, Math.round(BW * height / width));
if (!S.g || S.bw !== BW || S.bh !== BH) { S.g = createGraphics(BW, BH); S.g.pixelDensity(1); S.bw = BW; S.bh = BH; }

// ---- seed-dependent per-mode phase / jitter ----
if (S.seedUsed !== P.seed) {
  S.seedUsed = P.seed;
  const fr = i => { const s = Math.sin(i * 127.1 + P.seed * 311.7) * 43758.5453; return s - Math.floor(s); };
  S.ph0 = []; S.aj = []; S.cj = []; S.dr = [];
  for (let m = 0; m < 6; m++) { S.ph0[m] = fr(m + 1) * 6.2831853; S.aj[m] = (fr(m + 11) - 0.5) * 0.16; S.cj[m] = 0.9 + fr(m + 21) * 0.22; S.dr[m] = 0.08 + fr(m + 31) * 0.22; }
}

// ---- helpers ----
function hsv(h, s, v) { h = (((h % 360) + 360) % 360) / 60; const c = v * s, x = c * (1 - Math.abs(h % 2 - 1)), mm = v - c; let r, g, b; if (h < 1) { r = c; g = x; b = 0; } else if (h < 2) { r = x; g = c; b = 0; } else if (h < 3) { r = 0; g = c; b = x; } else if (h < 4) { r = 0; g = x; b = c; } else if (h < 5) { r = x; g = 0; b = c; } else { r = c; g = 0; b = x; } return [r + mm, g + mm, b + mm]; }
function cl(v) { return v < 0 ? 0 : v > 1 ? 1 : v; }
function lp(a, b, t) { return a + (b - a) * t; }

// ---- pattern lattice (6 mode directions) blended on section ----
const ANG = [0, 90, 60, 120, 30, 150];
const PAT = {
  squares: [1, 1, 0, 0, 0, 0],
  hex:     [1, 0, 1, 1, 0, 0],
  stripes: [1, 0, 0, 0, 0, 0],
  quasi:   [.82, .82, .82, .82, .82, .82],
  rhombic: [1, 0, 0, 0, 1, 1]
};
const SEQ = [PAT.squares, PAT.hex, PAT.stripes, PAT.quasi, PAT.squares, PAT.rhombic, PAT.hex, PAT.quasi];
const tgt = SEQ[((K.section | 0) % 8 + 8) % 8];
if (!S.w) S.w = tgt.slice();
for (let m = 0; m < 6; m++) S.w[m] = lp(S.w[m], tgt[m], 0.05);

// ---- time driven parameters (all from K.t → perpetual, never re-phases) ----
const spd = P.speed;
const rot = K.t * 0.014 * spd;                                  // lattice slowly re-tiles
const cellN = 3 + P.scale * 4.6 + K.intensity * 1.6 + P.density * 2.2;
const driveEnv = 1 - P.drive * 0.5 + P.drive * 0.5 * Math.sin(K.t * (0.9 + spd * 0.6)); // parametric vibration [1-drive,1]
const envC = cl(driveEnv + A.bass * 0.55);                      // caustic drive + kick
const caGain = (0.5 + P.energy * 1.15) * (0.55 + 0.45 * envC) + A.rms * 0.6;
const contrast = 0.5 + P.energy * 0.55;
const style = P.style, hueBase = P.hue;

// precompute per-mode wave vectors + traveling phase
const kx = [], ky = [], ph = [], wv = [];
let totW = 0;
for (let m = 0; m < 6; m++) {
  const we = S.w[m] * (m < 2 ? 1 : (0.3 + P.density * 0.7));
  wv[m] = we; totW += we;
  const a = (ANG[m] * Math.PI / 180) + rot + S.aj[m];
  const kk = 6.2831853 * cellN * S.cj[m];
  kx[m] = kk * Math.cos(a); ky[m] = kk * Math.sin(a);
  ph[m] = K.t * S.dr[m] * spd + S.ph0[m];
}
if (totW < 0.001) totW = 0.001;
const invW = 1 / totW;

// ---- render coarse height field ----
const g = S.g; g.loadPixels(); const px = g.pixels;
const ox = P.x, oy = P.y;
for (let j = 0; j < BH; j++) {
  const vv = (j / BW - oy * BH / BW);
  for (let i = 0; i < BW; i++) {
    const uu = (i / BW - ox);
    let h = 0, dhx = 0, dhy = 0;
    for (let m = 0; m < 6; m++) {
      const w = wv[m]; if (w < 0.01) continue;
      const arg = kx[m] * uu + ky[m] * vv + ph[m];
      const c = Math.cos(arg), s = Math.sin(arg);
      h += w * c; dhx += w * kx[m] * s; dhy += w * ky[m] * s;
    }
    const hn = h * invW;                                  // -1..1
    const slopeN = cl(Math.sqrt(dhx * dhx + dhy * dhy) * invW / (6.2831853 * cellN));
    const crest = cl(hn * contrast * 0.5 + 0.5);
    const spec = Math.pow(cl((crest - 0.6) / 0.4), 3) * caGain;   // sharp caustic on crests
    const edge = Math.pow(slopeN, 1.4);
    let r, gg, b;
    if (style === 'mercury') {
      const base = 0.10 + 0.52 * crest;
      const sp = Math.pow(crest, 5) * (0.7 + envC) + spec * 0.5;
      r = base * 0.94 + sp; gg = base + sp; b = base * 1.08 + sp * 1.05;
      r -= edge * 0.10; gg -= edge * 0.10; b -= edge * 0.08;
    } else if (style === 'thermal') {
      const t01 = cl(crest * 0.9 + spec * 0.3);
      r = cl(1.7 * t01 - 0.12);
      gg = cl(2.1 * t01 - 0.95);
      b = cl(3.2 * t01 - 2.3) + (t01 < 0.28 ? (0.28 - t01) * 1.5 : 0);
      const w2 = spec * 0.5; r += w2; gg += w2; b += w2 * 0.7;
    } else if (style === 'oil') {
      const hh = hueBase + crest * 190 + slopeN * 150 + driveEnv * 34;
      const co = hsv(hh, 0.62, 0.34 + 0.55 * crest);
      const w2 = spec * 0.55;
      r = co[0] + w2; gg = co[1] + w2 * 1.05; b = co[2] + w2 * 1.1;
    } else if (style === 'mono') {
      const gv = Math.pow(crest, 1.15);
      const sp = spec * 0.6;
      r = gv + sp; gg = gv + sp; b = gv + sp;
    } else { // water (default, backlit teal/indigo + caustics)
      const deep = hsv(hueBase + 34, 0.86, 0.17);
      const teal = hsv(hueBase, 0.82, 0.46);
      const pale = hsv(hueBase - 26, 0.42, 0.95);
      let br, bg, bb;
      if (crest < 0.6) { const t = crest / 0.6; br = lp(deep[0], teal[0], t); bg = lp(deep[1], teal[1], t); bb = lp(deep[2], teal[2], t); }
      else { const t = (crest - 0.6) / 0.4; br = lp(teal[0], pale[0], t); bg = lp(teal[1], pale[1], t); bb = lp(teal[2], pale[2], t); }
      r = br + spec * 0.72 + edge * 0.10 * 0.3;
      gg = bg + spec * 0.95 + edge * 0.14 * 0.5;
      b = bb + spec * 1.0 + edge * 0.16 * 0.6;
    }
    const o = 4 * (j * BW + i);
    px[o] = cl(r) * 255; px[o + 1] = cl(gg) * 255; px[o + 2] = cl(b) * 255; px[o + 3] = 255;
  }
}
g.updatePixels();

// ---- composite ----
push();
if (P.alpha < 100) tint(0, 0, 100, P.alpha);
image(g, 0, 0, width, height);
pop();

// ---- treble caustic sparkle overlay (partial, ADD, never full-frame flash) ----
if (A.treble > 0.02 || A.rms > 0.02) {
  push(); blendMode(ADD); noStroke();
  const gl = (A.treble * 0.6 + A.rms * 0.35) * (0.4 + P.energy);
  fill((hueBase - 20 + 360) % 360, 40, 100, cl(gl) * 20);
  rect(0, 0, width, height);
  blendMode(BLEND); pop();
}
